// Generated by AI (UnitTest MCP)
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, describe, expect, it } from "vitest";

import { findings, isSelfReferential } from "../../../scripts/no-shell-plumbing.mjs";

const guard = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../../scripts/no-shell-plumbing.mjs"
);
const temporaryDirectories = [];

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

describe("no-shell-plumbing", () => {
  it("flags documentation that instructs in a single-platform shell", () => {
    const found = findings("docs/USAGE.md", "Run this:\n\n```powershell\nGet-Item .\n```\n");

    expect(found).toHaveLength(1);
    expect(found[0].rule).toBe("single-platform-fence");
    expect(found[0].line).toBe(3);
  });

  it.each(["pwsh", "ps1", "cmd", "bat", "batch"])("flags a ```%s fence too", (tag) => {
    expect(findings("README.md", "```" + tag + "\nx\n```\n")).toHaveLength(1);
  });

  it("allows bash, which is the project's documented convention", () => {
    expect(
      findings("README.md", "```bash\nexport MINDLEAK_LLM_API_KEY=x\ncargo test --all\n```\n")
    ).toEqual([]);
  });

  it("allows an untagged or language fence", () => {
    expect(findings("README.md", "```\nplain\n```\n```rust\nfn main() {}\n```\n")).toEqual([]);
  });

  it("only applies the fence rule to documentation", () => {
    // A markdown fence inside source is a string, not an instruction.
    expect(findings("scripts/thing.mjs", 'const help = "```powershell";\n')).toEqual([]);
  });

  it.each([
    ['node -e "console.log(1)"', "node"],
    ["node --experimental-vm-modules -e 'x'", "node with flags"],
    ['python -c "import os"', "python"],
    ['python3 -c "import os"', "python3"],
    ["ruby -e 'puts 1'", "ruby"],
    ["perl -e 'print 1'", "perl"],
    ['powershell -Command "Get-Item"', "powershell"],
    ["pwsh -c 'Get-Item'", "pwsh"],
    ["cmd /c echo hi", "cmd"],
  ])("flags the inline interpreter one-liner %s", (line) => {
    const found = findings("Makefile", `\tsomething && ${line}\n`);

    expect(found).toHaveLength(1);
    expect(found[0].rule).toBe("inline-interpreter");
  });

  it("does not flag ordinary invocations of the same interpreters", () => {
    const text = [
      "node scripts/delivery-queue.mjs --dry-run",
      "npm --prefix editors/vscode test",
      "cargo test --all",
      "python -m pytest",
    ].join("\n");

    expect(findings("Makefile", text)).toEqual([]);
  });

  it("reports the line number and the offending text", () => {
    const found = findings("Makefile", 'ok\nalso ok\n\tnode -e "x"\n');

    expect(found[0].line).toBe(3);
    expect(found[0].text).toBe('node -e "x"');
    expect(found[0].detail).toMatch(/checked-in script/);
  });

  // A guard that forbids documenting the antipattern is unusable: the changelog
  // entry announcing this rule names `node -e` in prose, and would otherwise
  // have been its own first violation.
  it("lets documentation name the antipattern in prose", () => {
    const prose = 'Never use `node -e "..."` or `cmd /c` in a committed file.\n';

    expect(findings("CHANGELOG.md", prose)).toEqual([]);
  });

  it("still flags an interpreter one-liner inside a documentation fence", () => {
    const doc = ["Do this:", "", "```bash", 'node -e "console.log(1)"', "```", ""].join("\n");
    const found = findings("docs/USAGE.md", doc);

    expect(found).toHaveLength(1);
    expect(found[0].rule).toBe("inline-interpreter");
    expect(found[0].line).toBe(4);
  });

  it("resumes prose treatment after a fence closes", () => {
    const doc = ["```bash", "cargo test --all", "```", "", 'Avoid `python -c "x"` here.', ""].join(
      "\n"
    );

    expect(findings("docs/USAGE.md", doc)).toEqual([]);
  });

  it("exempts itself and its own test, which must contain the patterns", () => {
    expect(isSelfReferential("scripts/no-shell-plumbing.mjs")).toBe(true);
    expect(isSelfReferential("editors/vscode/scripts/no-shell-plumbing.test.mjs")).toBe(true);
    expect(isSelfReferential("scripts/other.mjs")).toBe(false);
    expect(findings("scripts/no-shell-plumbing.mjs", '```powershell\nnode -e "x"\n')).toEqual([]);
  });

  it("exits non-zero and names the file when run over a violating file", () => {
    const directory = mkdtempSync(join(tmpdir(), "mindleak-plumbing-"));
    temporaryDirectories.push(directory);
    const offender = join(directory, "GUIDE.md");
    writeFileSync(offender, "```powershell\nGet-Item .\n```\n");

    const result = spawnSync(process.execPath, [guard, offender], {
      encoding: "utf8",
      cwd: directory,
    });

    expect(result.status).toBe(5);
    expect(result.stderr).toMatch(/single-platform-fence/);
    expect(result.stderr).toMatch(/GUIDE\.md:1/);
  }, 30_000);

  it("passes over a clean file", () => {
    const directory = mkdtempSync(join(tmpdir(), "mindleak-plumbing-clean-"));
    temporaryDirectories.push(directory);
    const clean = join(directory, "GUIDE.md");
    writeFileSync(clean, "```bash\ncargo test --all\n```\n");

    const result = spawnSync(process.execPath, [guard, clean], {
      encoding: "utf8",
      cwd: directory,
    });

    expect(result.status, result.stderr).toBe(0);
  }, 30_000);

  // The guard is a ratchet: it only means anything if the tree it lands on is
  // already clean. If this fails, fix the file it names rather than the guard.
  it("passes over the whole tracked tree as it stands today", () => {
    const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "../../..");
    const result = spawnSync(process.execPath, [guard], { encoding: "utf8", cwd: repoRoot });

    expect(result.status, result.stderr).toBe(0);
  }, 60_000);

  it("ignores a file that no longer exists", () => {
    const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "../../..");
    const result = spawnSync(process.execPath, [guard, "docs/deleted-in-this-commit.md"], {
      encoding: "utf8",
      cwd: repoRoot,
    });

    expect(result.status, result.stderr).toBe(0);
  }, 30_000);
});

// Keep the import of execFileSync meaningful: the tree test above relies on the
// guard's own `git ls-files` walk, so confirm git is reachable from the repo.
describe("environment", () => {
  it("can list tracked files", () => {
    const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "../../..");
    const tracked = execFileSync("git", ["ls-files"], { cwd: repoRoot, encoding: "utf8" });

    expect(tracked).toMatch(/scripts\/scoped-commit\.mjs/);
  }, 30_000);
});
